function compileTemplate(source, translated) {
	const names = [];
	let pattern = "";
	let last = 0;
	for (const match of source.matchAll(PLACEHOLDER)) {
		pattern += source
			.slice(last, match.index)
			.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
		pattern += "([\\s\\S]+?)";
		names.push(match[1]);
		last = match.index + match[0].length;
	}
	pattern += source.slice(last).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
	const slots = new Map(names.map((name, index) => [name, index + 1]));
	return {
		re: new RegExp(`^${pattern}$`),
		render: (match) =>
			translated.replace(PLACEHOLDER, (token, name) => {
				const slot = slots.get(name);
				return slot ? match[slot] : token;
			}),
	};
}

for (const entry of DIALOGUE_DATA) {
	if (entry.d) DYNAMIC_OUTPUT.push(compileTemplate(entry.s, entry.v));
	else STATIC_OUTPUT.set(entry.s, entry.v);
}

function translateBareOutput(text) {
	const curated = CURATED_OUTPUT.get(text);
	if (curated !== undefined) return curated;
	for (const [pattern, render] of CURATED_DYNAMIC) {
		const match = text.match(pattern);
		if (match) return render(match);
	}
	const exact = STATIC_OUTPUT.get(text);
	if (exact !== undefined) return exact;
	for (const template of DYNAMIC_OUTPUT) {
		const match = text.match(template.re);
		if (match) return template.render(match);
	}
	return text;
}

/**
 * Translate a Verity-spoken line. Unknown text is deliberately untouched.
 * Formatting prefixes and all dynamic values remain byte-for-byte intact.
 * @param {unknown} text
 * @returns {unknown}
 */
export function translateOutput(text) {
	if (typeof text !== "string" || text.length === 0) return text;
	const direct = translateBareOutput(text);
	if (direct !== text) return direct;

	// Some call sites pass the already decorated chat line.
	const decorated = text.match(/^(<§eVerity§r>\s*)([\s\S]+)$/);
	if (decorated) {
		const body = translateBareOutput(decorated[2]);
		return body === decorated[2] ? text : decorated[1] + body;
	}
	return text;
}

