const ITEM_INPUT = [
	["con de", "goat"],
	["qua tao", "apple"],
	["go", "wood"],
	["ngoc ender", "ender pearl"],
	["xô nuoc", "water bucket"],
	["xo nuoc", "water bucket"],
	["go soi", "oak log"],
	["van go", "oak planks"],
	["duoc", "torch"],
	["mui ten", "arrow"],
	["dat", "dirt"],
	["da", "stone"],
	["hac dien thach", "obsidian"],
	["phoi sat", "iron ingot"],
	["phoi vang", "gold ingot"],
	["phoi netherite", "netherite ingot"],
	["thit bo chin", "steak"],
];

function foldVietnamese(value) {
	return value
		.toLocaleLowerCase("vi")
		.replace(/đ/g, "d")
		.normalize("NFD")
		.replace(/[\u0300-\u036f]/g, "")
		.replace(/[’']/g, "")
		.replace(/[?!,.;:]+/g, " ")
		.replace(/\s+/g, " ")
		.trim();
}

function protectInputTokens(value) {
	const values = [];
	const protectedText = value.replace(
		/\b[A-Za-z][A-Za-z0-9_.-]*:[A-Za-z0-9_./-]+\b/g,
		(token) => {
			const marker = `zzkeep${values.length}zz`;
			values.push(token);
			return marker;
		},
	);
	return {
		text: protectedText,
		restore: (result) =>
			result.replace(/\bzzkeep(\d+)zz\b/g, (marker, index) => values[Number(index)] ?? marker),
	};
}

/**
 * Normalize Vietnamese (accented or commonly unaccented) into phrases consumed
 * by the existing English intent router. Numbers and identifier characters survive.
 * @param {unknown} text
 * @returns {unknown}
 */
export function translateInput(text) {
	if (typeof text !== "string" || text.trim().length === 0) return text;

	const foldedEarly = foldVietnamese(text);
	for (const [pattern, replacement] of WHOLE_INPUT) {
		if (pattern.test(foldedEarly)) return replacement;
	}

	const names = protectProperNames(text);
	const protectedInput = protectInputTokens(names.text);
	const folded = foldVietnamese(protectedInput.text);

	for (const [pattern, replacement] of WHOLE_INPUT) {
		if (pattern.test(folded)) return names.restore(protectedInput.restore(replacement));
	}

	let output = ` ${folded} `;
	for (const [pattern, replacement] of PHRASE_INPUT) {
		output = output.replace(pattern, replacement);
	}
	if (/\b(?:give me|i want|i need)\b/.test(output)) {
		for (const [vi, en] of ITEM_INPUT) {
			const escaped = vi.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
			output = output.replace(new RegExp(`\\b${escaped}\\b`, "g"), en);
		}
	}
	output = output.replace(/^(.+?)\s+what is\s*$/g, "what is $1");
	output = output.replace(/\s+/g, " ").trim();

	return output === folded
		? text
		: names.restore(protectedInput.restore(output.replace(/\bverity\b/gi, "Verity")));
}
